public static class DataSerializer {
    public static string SerializeData(this object data, Formatting formatting = Formatting.None) {
        return data != null ? JObject.FromObject(data).ToString(formatting) : default(string);
    }
}

public class DataSerializer {

    private static final ObjectMapper converter = new ObjectMapper();

    public static String serializeData(Object data, boolean formattedOutput) {
        if (data == null) return null;
        try {
            if (formattedOutput) {
                converter.enable(SerializationFeature.INDENT_OUTPUT);
            } else {
                converter.disable(SerializationFeature.INDENT_OUTPUT);
            }
            return converter.writeValueAsString(data);
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }
}

